// Folder the page was served from (set by the web-demo bootstrap); "/" for a normal root deployment.
const BASE: string = (typeof window !== "undefined" && (window as any).__SS_BASE) || "/";
const cache = new Map<string, unknown>();
// Synchronous fetch keeps the content API identical to native. Files are cached after first use.
function loadJson<T>(url: string): T {
  if (!cache.has(url)) {
    const xhr = new XMLHttpRequest();
    xhr.open("GET", BASE + url, false);
    xhr.send(null);
    if (xhr.status < 200 || xhr.status >= 300) throw new Error(`Failed to load ${url}: ${xhr.status}`);
    cache.set(url, JSON.parse(xhr.responseText));
  }
  return cache.get(url) as T;
}

